-- Frozen sample of the state database at schema step 3 (BTN-198): the first PGlite version, the tables of the SQLite
-- steps 1 and 2 in Postgres, with the rows of the step 2 sample. A later step migrates it; this file is never edited.
create table schema_version (
  only_row    boolean primary key default true check (only_row),
  version     integer not null,
  migrated_at timestamptz not null default now()
);
insert into schema_version (version) values (3);
create table chain_flags (
  name  text primary key check (name in ('unattended', 'trimTools')),
  value text not null
);
create table chains (
  position   integer primary key,
  project_id text not null,
  chain      text not null
);
create table chain_queue (
  position   integer primary key,
  project_id text not null
);
create table chain_lists (
  project_id text not null,
  list       text not null check (list in ('orders', 'skipped', 'leftovers', 'released', 'ci')),
  value      text not null,
  primary key (project_id, list)
);
create table questions (
  position   integer primary key,
  task       text not null,
  session_id text not null,
  ask        text not null,
  comment    text not null,
  done       boolean not null default false
);
create table launches (
  id         integer generated by default as identity primary key,
  at         text not null,
  project_id text not null,
  task       text not null,
  session_id text not null,
  reason     text,
  extra      text not null default '{}'
);
create index launches_session on launches (session_id);
create index launches_task on launches (task);
create table handoffs (
  session_id text primary key,
  at         text,
  task       text,
  previous   text,
  reason     text,
  prompt     text,
  note_path  text,
  note       text
);
create table closed_tasks (
  project_id text not null,
  task       text not null,
  tracker    text not null,
  title      text not null,
  url        text,
  closed_at  text not null,
  primary key (project_id, task)
);
create table mailbox (
  id         integer generated by default as identity primary key,
  task       text not null,
  session_id text not null,
  text       text not null,
  files      text not null default '[]',
  posted_at  text not null,
  fate       text not null check (fate in ('waiting', 'delivered', 'returned', 'dismissed')),
  event      text,
  settled_at text
);
create index mailbox_session on mailbox (session_id);
